"""Short introductory additions, drafted only after the saved passages were read."""
from other_handbooks import e,b

def r(book,loc,m=False,segments=None):return ('p-'+('m-' if m else '')+book+'-'+loc,segments or [1])
def entry(id,title,group,first,second):
 return e(id,title,group,[b('meaning',first[0],first[1],first[2],by=first[3] if len(first)>3 else 'ביאור ערוך על פי הרמב״ם'),b('distinction',second[0],second[1],second[2],by=second[3] if len(second)>3 else 'ביאור ערוך על פי הרמב״ם')])

